public RefreshFrequency xds()
{
    METUserSecurityGroupList  metUserSecurityGroupList;
    METUserSecurityGroup      metUserSecurityGroup;

    unchecked(Uncheck::XDS)
    {
        METModuleCustVend moduleCustVend = METUserSecurityGroup::findSingleRebateModuleByUser();

        Set modulesToInsert = this.getModulesToInsert(moduleCustVend);
        this.insertModules(modulesToInsert);
    }

    return RefreshFrequency::PerSession;
}

private Set getModulesToInsert(METModuleCustVend _moduleCustVend)
{
    Set modules = new Set(Types::Enum);

    switch (_moduleCustVend)
    {
        case METModuleCustVend::NotApplicable:
            modules.add(ModuleInventCustVend::Cust);
            modules.add(ModuleInventCustVend::Vend);
            modules.add(ModuleInventCustVend::Invent);
            break;
        case METModuleCustVend::Cust:
            modules.add(ModuleInventCustVend::Cust);
            break;
        case METModuleCustVend::Vend:
            modules.add(ModuleInventCustVend::Vend);
            break;
    }

    return modules;
}

private void insertModules(Set _modules)
{
    METTAMRebateModulePolicyTmp tmp;
    SetEnumerator enumerator = _modules.getEnumerator();

    while (enumerator.moveNext())
    {
        tmp.clear();
        tmp.ModuleInventCustVend = enumerator.current();
        tmp.insert();
    }
}
